insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-f26962fd54e3', 'it', 'A1', 'Presente Regolare e Frequenti Irregolari', 'Nesta lição, você vai aprender o presente do indicativo dos verbos regulares (-are, -ere, -ire) e alguns verbos irregulares muito comuns, como essere, avere, fare, andare, dare, stare, dire, uscire, venire e bere. Esses verbos são essenciais para falar sobre ações habituais e fatos do dia a dia.', 'Para verbos regulares, tire a terminação -are, -ere, -ire e adicione as terminações do presente: -o, -i, -a, -iamo, -ete, -ono (para -are e -ere) e -o, -i, -e, -iamo, -ite, -ono (para -ire). Verbos irregulares têm formas próprias que devem ser memorizadas.', '["Para expressar ações habituais ou rotinas: ''Ogni giorno bevo un caffè.''","Para fatos gerais ou verdade universal: ''L''acqua bolle a 100 gradi.''","Para ações no momento da fala (presente contínuo, embora na prática use-se ''stare + gerundio''): ''Che cosa fai? Leggo un libro.''","Para expressar preferências: ''Preferisco il tè al caffè.''"]'::jsonb, '["Confundir ''sono'' (essere) com ''sono'' (verbo ''stare'' na 1a pessoa?) – na verdade, estão corretos, mas cuidado com a conjugação de ''stare''.","Usar ''fa'' em vez de ''faccio'' para a 1a pessoa de ''fare''.","Esquecer que ''andare'' é irregular: ''io vado'', não ''ando''.","Confundir ''escono'' (uscire) com ''escono''? – na verdade, não é comum, mas cuidado com a conjugação.","Usar ''beco'' em vez de ''bevo'' para o verbo ''bere''."]'::jsonb, '["Os verbos modais ''potere'', ''dovere'', ''volere'' também são irregulares e frequentemente usados.","O presente é usado com expressões como ''sempre'', ''di solito'', ''mai'', ''ogni giorno''.","Na forma negativa, basta colocar ''non'' antes do verbo.","As perguntas podem ser feitas com entonação ou com ''Che...?'', ''Come...?'' etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

