insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-22c949894746', 'it', 'A1', 'Il verbo essere e i pronomi soggetto', 'Nesta lição, você vai aprender o verbo essere (ser/estar) e os pronomes pessoais sujeito em italiano. Essa é a base para formar frases simples e se apresentar.', 'O verbo essere é irregular. Conjugação no presente: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono. Os pronomes sujeito: io (eu), tu (você), lui/lei (ele/ela), noi (nós), voi (vocês), loro (eles/elas). Muitas vezes, o pronome é omitido porque a forma do verbo já indica a pessoa.', '["Para se apresentar: Io sono Marco.","Para falar nacionalidade: Tu sei brasiliana?","Para descrever características: Lui è alto.","Para indicar profissão: Noi siamo insegnanti.","Para expressar estado: Voi siete stanchi?","Para localizar: Loro sono a casa."]'::jsonb, '["Confundir ''tu'' (informal) com ''Lei'' (formal). Use ''Lei'' com pessoas que você não conhece bem.","Usar o pronome quando não é necessário: ''Io sono'' é correto, mas frequentemente se diz apenas ''Sono''.","Usar ''è'' para ''eles'' e ''sono'' para ''ele''. Lembre-se: ''è'' é para ele/ela, ''sono'' para eles/elas."]'::jsonb, '["Em italiano, o pronome sujeito é opcional na maioria dos casos. Use-o para dar ênfase ou evitar ambiguidade."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

