insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-53edfb883159', 'it', 'A1', 'Possessivi e Dimostrativi', 'Nesta lição, você vai aprender a usar os possessivos (meu, seu, nosso etc.) e os demonstrativos (este, esse, aquele) em italiano. Essas palavras ajudam a indicar posse e a localizar pessoas ou objetos no espaço e no tempo.', '**Possessivi**: Os possessivos concordam em gênero e número com o substantivo. Exemplos: mio (meu), mia (minha), miei (meus), mie (minhas); tuo/tua/tuoi/tue (seu/sua); suo/sua/suoi/sue (dele/dela); nostro/nostra/nostri/nostre (nosso); vostro/vostra/vostri/vostre (vosso); loro (invariável).

**Dimostrativi**: Questo (este) e quello (aquele) também concordam com o substantivo. Questo: questo/questa/questi/queste; Quello: quello/quel/quella/quelle (masculino singular tem formas contractas: quel + consoante, quello + s+consoante/z, quell'' + voglia).', '["Para indicar posse: Questo è il mio libro. (Este é meu livro.)","Para indicar proximidade: Questa casa è bella. (Esta casa é bonita.)","Para indicar distância: Quella macchina è di Marco. (Aquele carro é do Marco.)","Para contrastar: Questo è mio, quello è tuo. (Este é meu, aquele é seu.)"]'::jsonb, '["Confundir `questo` com `quello` – lembre que `questo` é perto e `quello` é longe.","Esquecer de concordar o possessivo com o substantivo: dizer `mia libro` em vez de `mio libro`.","Usar `loro` como variável, mas ele é invariável: `il loro libro`, `la loro casa`.","Confundir `suo` com `loro`: `suo` é ''dele/dela'' e `loro` é ''deles/delas''."]'::jsonb, '["Em italiano, os possessivos geralmente vêm antes do substantivo e requerem artigo definido, exceto com nomes de parentesco no singular: `mio padre` (meu pai), mas `il mio libro` (meu livro)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

