insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-5598a4b48f47', 'it', 'A1', 'Simple and Articulated Prepositions', 'As preposições simples (di, a, da, in, con, su, per, tra, fra) são palavras que ligam ideias. Quando combinadas com artigos definidos (il, lo, la, i, gli, le), formam as preposições articuladas (del, allo, dalla, nel, sul, ecc.).', 'Preposição + artigo definido = preposição articulada.
Exemplos:
di + il = del
a + la = alla
da + lo = dallo
in + i = nei
su + le = sulle
Algumas combinações são irregulares: con + il = col (mais comum) ou con il.', '["Indicar posse com ''del'' (di + il): ''Il libro del professore''.","Indicar movimento ou direção com ''alla'' (a + la): ''Vado alla stazione''.","Indicar proveniência com ''dalla'' (da + la): ''Vengo dalla scuola''.","Indicar localização com ''nel'' (in + il): ''Il gatto è nel giardino''.","Indicar tema com ''sul'' (su + il): ''Un libro sulla storia''."]'::jsonb, '["Usar a preposição simples quando deveria usar a articulada, por exemplo: ''vado a scuola'' (correto) mas ''vado alla scuola'' (errado, a menos que seja específico).","Esquecer de combinar com o artigo definido, como em ''il libro di il professore'' (errado) em vez de ''il libro del professore''.","Trocar a preposição, como ''a'' em vez de ''in'' em algumas expressões: ''vado in Brasile'' (errado) em vez de ''vado a Brasile''? Na verdade, ''vado in Italia'' usa ''in'', e ''vado a Roma'' usa ''a''."]'::jsonb, '["As preposições articuladas são mais comuns na fala do que as simples.","Algumas combinações não são usadas com frequência, como ''con la'' que se torna ''con la'' (não se funde) ou ''colla'' (arcaico).","No A1, é importante reconhecer as formas mais comuns: del, dello, della, dei, degli, delle; al, allo, alla, ai, agli, alle; dal, dallo, dalla, dai, dagli, dalle; nel, nello, nella, nei, negli, nelle; sul, sullo, sulla, sui, sugli, sulle."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

