insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-8b622c1c0641', 'it', 'A1', 'Mi piace: Expressing Likes and Dislikes', 'Nesta lição, você vai aprender a usar ''mi piace'' para expressar o que você gosta. Em italiano, a estrutura é um pouco diferente do português: usamos o pronome indireto ''mi'' (a mim) e o verbo ''piacere'' (agradar).', 'Para dizer que você gosta de algo no singular, use ''mi piace'' + substantivo singular ou verbo no infinitivo. Para plural, use ''mi piacciono'' + substantivo plural. A mesma estrutura vale para outras pessoas: ti piace/piacciono (você), gli/le piace/piacciono (ele/ela), ci piace/piacciono (nós), vi piace/piacciono (vocês), gli piace/piacciono (eles/elas).', '["Para expressar gostos pessoais: ''Mi piace la pizza'' (Eu gosto de pizza).","Para expressar preferências: ''Mi piace leggere'' (Eu gosto de ler).","Para perguntar sobre gostos: ''Ti piace il caffè?'' (Você gosta de café?).","Para expressar desgostos: ''Non mi piace il caldo'' (Eu não gosto do calor).","Para falar de coisas no plural: ''Mi piacciono i libri'' (Eu gosto de livros)."]'::jsonb, '["Errado: ''Io piace la pizza'' – Correta: ''Mi piace la pizza'' (não use ''io'' como sujeito).","Errado: ''Mi piace i libri'' – Correta: ''Mi piacciono i libri'' (verbo concorda com o objeto).","Errado: ''Mi piacciono la pizza'' – Correta: ''Mi piace la pizza'' (singular com singular).","Errado: ''Mi piace leggere e scrivere'' – Esta é correta: verbos no infinitivo sempre usam ''piace''."]'::jsonb, '["O verbo ''piacere'' concorda com a coisa que agrada, não com a pessoa que gosta.","Use o artigo definido com substantivos: ''Mi piace il gelato'' (o sorvete).","Para negar, coloque ''non'' antes do pronome: ''Non mi piace''.","Para enfatizar o sujeito, diga ''A me mi piace''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

