insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-21faf516b6d9', 'it', 'A1', 'Quantità di base: quanto, quanti, troppi, abbastanza, poco', 'Nesta lição, você vai aprender a falar sobre quantidades básicas em italiano. Vamos ver como usar palavras como ''quanto'' (quanto), ''quanti'' (quantos), ''troppo'' (muito/demais), ''abbastanza'' (suficiente) e ''poco'' (pouco). Essas palavras são muito úteis no dia a dia para fazer perguntas, comparar e descrever quantidades.', 'Quanto e quanti: ''Quanto'' é usado com substantivos masculinos singulares (quanto pane? - quanto pão?) e ''quanti'' com substantivos masculinos plurais (quanti libri? - quantos livros?). Para feminino, use ''quanta'' (singular) e ''quante'' (plural). 

Troppo: pode ser invariável (troppo pane - muito pão) ou variável (troppa pasta - muita massa, troppi libri - muitos livros, troppe parole - muitas palavras). 

Abbastanza: é invariável (abbastanza tempo - tempo suficiente, abbastanza soldi - dinheiro suficiente). 

Poco: varia em gênero e número (poco zucchero - pouco açúcar, poca acqua - pouca água, pochi amici - poucos amigos, poche cose - poucas coisas).', '["Para perguntar sobre quantidade: Quanto costa? (Quanto custa?), Quanti anni hai? (Quantos anos você tem?)","Para expressar excesso: Ho troppo lavoro. (Tenho muito trabalho.)","Para indicar suficiência: Ho abbastanza tempo. (Tenho tempo suficiente.)","Para indicar insuficiência: C''è poca acqua. (Há pouca água.)","Para comparar quantidades: Quanti caffè bevi al giorno? (Quantos cafés você bebe por dia?)"]'::jsonb, '["Usar ''quanto'' para plural: Errado: Quanto libri? Certo: Quanti libri?","Usar ''troppo'' invariável com substantivos femininos: Errado: Ho troppo amiche. Certo: Ho troppe amiche.","Confundir ''abbastanza'' com ''molto'': ''Abbastanza'' significa ''suficiente'', não ''muito''.","Esquecer de concordar ''poco'' com o substantivo: Errado: Ho poco amici. Certo: Ho pochi amici."]'::jsonb, '["Em italiano, ''quanto'' também pode ser usado em exclamações: Quanto tempo! (Quanto tempo!) \n\n''Troppo'' também pode significar ''demais'' (e.g., Questo è troppo - Isso é demais). \n\n''Abbastanza'' é invariável, mas pode ser usado como advérbio: Sei abbastanza alto. (Você é bastante alto.)"]'::jsonb, 0, true)
