insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-9dd7819bcd76', 'it', 'A1', 'Verbi Essere, Avere, Andare e Fare', 'Os verbos essere, avere, andare e fare são essenciais para começar a falar italiano. Eles são irregulares e muito usados no dia a dia. Vamos aprender suas conjugações no presente e quando usá-los.', 'Presente do indicativo:
- Essere: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono
- Avere: io ho, tu hai, lui/lei ha, noi abbiamo, voi avete, loro hanno
- Andare: io vado, tu vai, lui/lei va, noi andiamo, voi andate, loro vanno
- Fare: io faccio, tu fai, lui/lei fa, noi facciamo, voi fate, loro fanno', '[{"case":"Essere","description":"Usa ''essere'' para identidade, nacionalidade, profissão, características e estado.","example":"Io sono Maria. / Sono brasiliana. / Sono stanco."},{"case":"Avere","description":"Usa ''avere'' para posse, idade e expressões como ''avere fame'' e ''avere sete''.","example":"Ho un gatto. / Quanti anni hai? / Ho fame."},{"case":"Andare","description":"Usa ''andare'' para movimento (ir) e também para expressar como algo está.","example":"Vado a Roma. / Come va?"},{"case":"Fare","description":"Usa ''fare'' para ações, atividades, tempo e expressões como ''fare freddo''.","example":"Faccio la doccia. / Che tempo fa? / Fa freddo."}]'::jsonb, '["Confundir ''è'' (verbo essere) com ''e'' (conjunção ''e''). ''è'' tem acento.","Usar ''essere'' para idade em vez de ''avere'': em italiano se usa ''avere'' (ho 25 anni).","Confundir ''sono'' (io sono) com ''sonno'' (substantivo, sono).","Esquecer que ''andare'' e ''fare'' têm as formas ''va'' e ''fa'' na terceira pessoa, sem acento."]'::jsonb, '["Essere (ser/estar) é usado para identidade, nacionalidade, profissão, características e estados temporários ou permanentes.","Avere (ter) é usado para posse, idade e expressões como ''avere fame'' (ter fome) e ''avere sete'' (ter sede).","Andare (ir) indica movimento para um lugar, e também é usado em expressões como ''andare bene'' (funcionar bem).","Fare (fazer) é usado para ações e atividades, e também para falar sobre o tempo, como ''fa freddo'' (faz frio)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

