insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-44576954c49e', 'it', 'A1', 'Presente Regolare e Frequenti Irregolari', 'Nesta aula, você vai aprender o presente do indicativo dos verbos regulares (-are, -ere, -ire) e de alguns verbos irregulares muito usados, como essere, avere, fare, andare, stare e dare. O presente é usado para falar de ações habituais, fatos verdadeiros e situações atuais. Você vai ver as formas, como usá-las e alguns erros comuns. No final, há exercícios para praticar.', 'Para formar o presente dos verbos regulares, pegue o infinitivo e acrescente as terminações:
- Verbi in -ARE (es. parlare): parlo, parli, parla, parliamo, parlate, parlano
- Verbi in -ERE (es. leggere): leggo, leggi, legge, leggiamo, leggete, leggono
- Verbi in -IRE (es. dormire): dormo, dormi, dorme, dormiamo, dormite, dormono
Os verbos irregulares mais comuns têm formas próprias:
- essere: sono, sei, è, siamo, siete, sono
- avere: ho, hai, ha, abbiamo, avete, hanno
- fare: faccio, fai, fa, facciamo, fate, fanno
- andare: vado, vai, va, andiamo, andate, vanno
- stare: sto, stai, sta, stiamo, state, stanno
- dare: do, dai, dà, diamo, date, danno', '["Ações habituais: Ogni giorno mangio una mela.","Verdades gerais: L''acqua bolle a 100 gradi.","Ações atuais: Ora leggo un libro.","Com expressões de tempo: Oggi andiamo al mare."]'::jsonb, '["Confundire essere e stare: ''Come stai?'' (não ''Come sei?'')","Usar ''fa'' no lugar de ''c''è'' para clima: ''Oggi fa caldo'' (não ''Oggi è caldo'')","Esquecer o ''h'' no verbo avere: ho, hai, ha (não ''o'', ''ai'', ''a'')","Usar ''è'' para ''e'' (conjunção): ''Marco è italiano e simpatico''","Confundir ''sono'' (io sono) com ''sono'' (loro sono) - mesma forma, mas contexto"]'::jsonb, '["O presente também pode expressar futuro próximo com expressões como ''domani''.","Os verbos modais (potere, dovere, volere) são irregulares, mas veremos em outra aula.","Preste atenção à pronúncia: ''sono'' com som de ''o'' fechado.","Use ''c''è'' (singular) e ''ci sono'' (plural) para existência: ''C''è un bar qui'', ''Ci sono due bar''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

