insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-ba21d7e83287', 'it', 'A1', 'I verbi riflessivi', 'Os verbos reflexivos em italiano são usados quando a ação recai sobre o próprio sujeito. Eles são formados com os pronomes reflexivos e são muito comuns nas rotinas diárias.', 'Estrutura: pronome reflexivo + verbo conjugado + (opcional) complemento. Exemplo: (io) mi lavo = eu me lavo. Os pronomes reflexivos são: mi (me), ti (te), si (se), ci (nos), vi (vos), si (se).', '["Para ações da rotina diária: alzarsi (levantar-se), lavarsi (lavar-se), vestirsi (vestir-se).","Para ações recíprocas: incontrarsi (encontrar-se), amarsi (amar-se).","Para expressar emoções ou sentimentos: sentirsi (sentir-se), arrabbiarsi (ficar com raiva).","Para ações involuntárias: addormentarsi (adormecer), svegliarsi (acordar)."]'::jsonb, '["Esquecer o pronome reflexivo: dizer ''io lavo'' em vez de ''io mi lavo''.","Usar o pronome errado: ''mi'' em vez de ''si'' para a terceira pessoa.","Colocar o pronome depois do verbo em frases afirmativas (isso é usado em imperativos ou infinitivos, não no presente).","Confundir verbos reflexivos com verbos não reflexivos, como ''mangiare'' (comer) que não é reflexivo."]'::jsonb, '["No passato prossimo, os verbos reflexivos usam o auxiliar ''essere''. O pronome reflexivo vem antes do verbo auxiliar. Exemplo: ''Mi sono alzato/a'' (Eu me levantei). O particípio passado concorda com o sujeito."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

