insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-7b1ebf778661', 'it', 'A1', 'Negazione e Domande in Italiano', 'In questa lezione, imparerai come formare frasi negative e domande in italiano. Queste sono abilità fondamentali per comunicare in modo efficace.', 'Per formare una frase negativa, metti ''non'' prima del verbo. Per formare una domanda, alzi l''intonazione alla fine della frase. Le parole interrogative come ''chi'', ''che cosa'', ''dove'', ''quando'', ''perché'' aiutano a fare domande specifiche.', '["Per negare un''azione: ''Io non mangio carne.''","Per fare domande sì/no: ''Mangi carne?''","Per chiedere informazioni: ''Dove vivi?''"]'::jsonb, '["Mettere ''non'' dopo il verbo.","Dimenticare l''intonazione interrogativa.","Usare ''no'' invece di ''non''."]'::jsonb, '["In italiano, l''ordine delle parole non cambia per le domande. L''intonazione è importante."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

