insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-b374151144b1', 'it', 'A1', 'Aggettivi e Pronomi Dimostrativi: Questo e Quello', 'Nesta lição, você vai aprender a usar ''questo'' e ''quello'' para indicar pessoas, objetos e lugares próximos ou distantes. Esses adjetivos são essenciais para descrever e identificar coisas no dia a dia.', 'QUEST'' (before vowel) / QUESTO (m.sg.) / QUESTA (f.sg.) / QUESTI (m.pl.) / QUESTE (f.pl.)
QUEL (m.sg. before consonant) / QUELL'' (m.sg. before vowel) / QUELLA (f.sg.) / QUELLI (m.pl.) / QUELLE (f.pl.)
Examples: questo libro, questa casa, questi amici, queste amiche; quel gatto, quell''uomo, quella donna, quelli studenti, quelle ragazze.', '["Usa ''questo'' e le sue forme per indicar algo próximo de quem fala (em distância ou tempo).","Usa ''quello'' e as suas formas para indicar algo distante de quem fala e de quem ouve.","Use ''questo'' também para introduzir um tópico ou para se referir a algo que vai ser dito.","Use ''quello'' para se referir a algo já mencionado ou conhecido."]'::jsonb, '["Confundir ''questo'' (isto/este) com ''quello'' (aquele).","Usar ''quello'' antes de consoante quando deveria ser ''quel'', e ''quello'' antes de vogal quando deveria ser ''quell''.","Esquecer de concordar o adjetivo com o substantivo em gênero e número."]'::jsonb, '["Em italiano, os adjetivos demonstrativos concordam em gênero e número com o substantivo.","As formas troncate ''quest'''', ''quell'''', ''quel'' são usadas antes de vogais (quest''uomo, quell''amico) e ''quel'' antes de consoante (quel libro).","''Quello'' tem a forma ''quello'' também como pronome (não acompanha substantivo) e varia: quello (m.sg.), quella (f.sg.), quelli (m.pl.), quelle (f.pl.).","Em situações informais, ''sto'', ''sta'', ''sti'', ''ste'' são usados como abreviação de ''questo'', etc."]'::jsonb, 0, true)
