insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-e1f2a5784207', 'it', 'A1', 'Potere, Volere, Dovere (Basic)', 'Nesta lição, você vai aprender os verbos modais mais importantes em italiano: potere (poder), volere (querer) e dovere (dever). Esses verbos são essenciais para expressar possibilidade, vontade e obrigação, e são usados em muitas situações do dia a dia.', 'Os verbos modais são geralmente seguidos de um verbo no infinitivo. Eles são conjugados de forma irregular no presente do indicativo:

- **Potere**: io posso, tu puoi, lui/lei può, noi possiamo, voi potete, loro possono.
- **Volere**: io voglio, tu vuoi, lui/lei vuole, noi vogliamo, voi volete, loro vogliono.
- **Dovere**: io devo, tu devi, lui/lei deve, noi dobbiamo, voi dovete, loro devono.', '["Para pedir permissão (potere): Posso entrare? (Posso entrar?)","Para expressar vontade (volere): Voglio un caffè. (Quero um café.)","Para expressar obrigação (dovere): Devo studiare. (Devo estudar.)"]'::jsonb, '["Não confundir ''potere'' com ''sapere'' (saber como fazer algo). ''Posso nuotare'' significa ''I can swim'' (permissão/habilidade física); ''So nuotare'' significa ''I know how to swim''.","Não esquecer que após o verbo modal, o verbo principal fica no infinitivo (não conjugado): ''Voglio mangiare'' (não ''Voglio mangio'')."]'::jsonb, '["Esses verbos também são usados em expressões educadas, como ''Potrei...?'' para ''Poderia...?''.","No passado, ''dovere'' e ''potere'' mudam de significado dependendo do contexto."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

