insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-e1dd842acdf9', 'it', 'A1', 'Preposizioni semplici e articolate', 'Nesta lição, você vai aprender as preposições simples e articuladas em italiano. As preposições simples são palavras como ''di'', ''a'', ''da'', ''in'', ''con'', ''su'', ''per'', ''tra'', ''fra''. Quando combinadas com artigos definidos (il, lo, la, i, gli, le), formam as preposições articuladas, como ''del'', ''al'', ''dal'', ''nel'', ''col'', ''sul''. Vamos ver como usá-las no dia a dia!', 'As preposições articuladas são formadas pela união de uma preposição simples com um artigo definido. Por exemplo: di + il = del, a + il = al, da + il = dal, in + il = nel, su + il = sul, con + il = col (mais comum na fala). A tabela completa inclui todas as combinações com os artigos: il, lo, l'', la, i, gli, le.', '[{"use_case":"Indicare possesso o provenienza: ''Il libro è di Maria'' → ''Il libro è della biblioteca''."},{"use_case":"Indicare luogo (stato o moto): ''Vado a Roma'' → ''Vado al cinema''."},{"use_case":"Indicare mezzo: ''Viaggio in treno'' → ''Viaggio col treno''."},{"use_case":"Indicare argomento: ''Parlo di calcio'' → ''Parlo del calcio''."},{"use_case":"Indicare tempo: ''Lavoro di notte'' → ''Lavoro di notte'' (mas pode ser ''nella notte'')."}]'::jsonb, '[{"mistake":"Usar a preposição simples em vez de articulada quando é obrigatória: ''Vado a cinema'' (errado) → ''Vado al cinema'' (certo)."},{"mistake":"Esquecer a concordância com o artigo: ''con il'' vira ''col'', mas ''con lo'' vira ''con lo'' ou ''collo''? Na verdade, ''con lo'' geralmente fica ''con lo'', mas ''col'' é usado com ''il''."},{"mistake":"Confundir ''di'' com ''da'' em expressões de origem: ''Vengo da Brasile'' (errado) → ''Vengo dal Brasile'' (certo)."},{"mistake":"Usar ''in'' com países sem artigo: ''Vado in Brasile'' (errado) → ''Vado in Brasile'' é usado sem artigo, mas com artigo definido para regiões: ''Vado nel Lazio''."}]'::jsonb, '["Nota: As preposições articuladas são muito comuns na fala e na escrita. Preste atenção nas contrações com ''lo'' e ''gli'': ''dello'', ''allo'', ''dallo'', ''nello'', ''sullo''. Com ''l'' antes de vogal: ''dell'', ''all'', ''dall'', ''nell'', ''sull''. Boa sorte!"]'::jsonb, 0, true)
