insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-dfd79d4842df', 'it', 'A1', 'Mi piace / Non mi piace', 'Nesta lição, você vai aprender a expressar gostos e preferências em italiano usando ''mi piace'' e ''non mi piace''.', 'Para dizer que você gosta de algo, use ''mi piace'' + singular (ex: Mi piace il caffè) e ''mi piacciono'' + plural (ex: Mi piacciono le mele). Para negar, use ''non'' antes: ''Non mi piace'' / ''Non mi piacciono''.', '["Para expressar preferências pessoais: Mi piace la pizza.","Para falar sobre atividades: Mi piace leggere.","Para expressar desgostos: Non mi piace il caldo.","Para concordar ou discordar: A: Mi piace il gelato. B: Anche a me! / A me no."]'::jsonb, '["Usar ''mi piace'' com substantivos no plural: ''Mi piace le mele'' (errado) -> ''Mi piacciono le mele'' (correto).","Esquecer o ''non'' em frases negativas: ''Mi piace il caldo'' quando você quer dizer que não gosta (errado) -> ''Non mi piace il caldo'' (correto).","Confundir ''mi piace'' com ''io piace'': o correto é ''mi piace'', não ''io piace''.","Usar ''piacere'' com artigo indefinido sem necessidade: ''Mi piace una pizza'' (quando fala de pizza em geral) -> prefira ''Mi piace la pizza''."]'::jsonb, '["Use ''mi piace'' antes de verbos no infinitivo: Mi piace cantare.","Para perguntar sobre gostos: ''Ti piace...?'' (informal) ou ''Le piace...?'' (formal).","Para pessoas, use ''mi piace'' seguido de nome ou pronome: Mi piace Marco.","Lembre-se: ''piacere'' significa literalmente ''agradar'', então a estrutura é diferente do português."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

