insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-0b903ccde66c', 'it', 'A1', 'Verbi Essere, Avere, Andare, Fare', 'Nesta lição, você vai aprender quatro verbos essenciais em italiano: essere (ser/estar), avere (ter), andare (ir) e fare (fazer). Eles são irregulares e muito usados no dia a dia. Você vai ver como conjugá-los no presente e em quais situações usá-los.', 'Presente do indicativo:
- Essere: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono
- Avere: io ho, tu hai, lui/lei ha, noi abbiamo, voi avete, loro hanno
- Andare: io vado, tu vai, lui/lei va, noi andiamo, voi andate, loro vanno
- Fare: io faccio, tu fai, lui/lei fa, noi facciamo, voi fate, loro fanno', '["Essere: para identidade, origem, profissão, características físicas e estado civil. Ex.: Io sono Maria. (Eu sou Maria.)","Essere: para estado temporário ou localização. Ex.: Oggi è freddo. (Hoje está frio.) / Il libro è sul tavolo. (O livro está na mesa.)","Avere: para posse e idade. Ex.: Ho una macchina. (Eu tenho um carro.) / Quanti anni hai? (Quantos anos você tem?)","Andare: para movimento e para ir a lugares. Ex.: Vado a Roma. (Vou a Roma.)","Fare: para ações, atividades e clima. Ex.: Faccio colazione alle 7. (Tomo café da manhã às 7.) / Oggi fa caldo. (Hoje está quente.)"]'::jsonb, '["Confundir essere e avere em expressões como ''ho fame'' (tenho fome) e não ''sono fame''.","Usar ''avere'' para idade em vez de ''essere''. Ex.: ''Ho 20 anni'' e não ''Sono 20 anni''.","Esquecer que andare pede preposição ''a'' antes de lugares. Ex.: ''Vado a casa'' e não ''Vado casa''.","Confundir as formas ''è'' (é) e ''e'' (e). ''È'' tem acento.","Errar a conjugação de ''fare'': ''faccio'' e não ''fago''."]'::jsonb, '["Esses verbos são irregulares, então é importante memorizar as formas. Pratique com frases do seu dia a dia.","Preste atenção ao uso da preposição ''a'' depois de ''andare'' para indicar lugares.","Use ''fare'' para falar de atividades e também do clima."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

