insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-77b00c2a28f5', 'it', 'A1', 'Pronomi Personali Soggetto', 'Os pronomes pessoais sujeito em italiano indicam quem realiza a ação do verbo. Eles são essenciais para formar frases corretas e para entender quem está falando ou de quem se fala.', 'Os pronomes pessoais sujeito em italiano são: io (eu), tu (você), lui/lei (ele/ela), noi (nós), voi (vocês), loro (eles/elas). A forma ''lei'' também é usada como tratamento formal para ''você''.', '["Para falar de si mesmo: Io sono Maria.","Para falar com alguém diretamente: Tu sei molto gentile.","Para falar de outra pessoa: Lui lavora a Roma, Lei abita a Firenze.","Para falar de um grupo que inclui o falante: Noi andiamo al cinema.","Para falar com um grupo: Voi siete studenti.","Para falar de um grupo de outras pessoas: Loro sono brasiliani."]'::jsonb, '["Usar ''tu'' em situações formais: em italiano, o tratamento formal é ''lei'', não ''tu''.","Esquecer o pronome sujeito: embora possa ser omitido, é importante usá-lo para dar ênfase ou evitar ambiguidade.","Confundir ''lei'' (ela) com ''Lei'' (tratamento formal): a diferença é apenas formal, mas na escrita costuma-se capitalizar no tratamento formal."]'::jsonb, '["Em italiano, o pronome sujeito é frequentemente omitido porque a terminação do verbo já indica a pessoa. Porém, usamos o pronome para ênfase ou contraste. Para falar com pessoas mais velhas ou em contextos profissionais, use ''Lei'' em vez de ''tu''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

