insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-57d23a2875ff', 'it', 'A1', 'La Negazione e le Domande in Italiano', 'Nesta lição, você vai aprender a formar frases negativas e a fazer perguntas simples em italiano. Isso é essencial para se comunicar no dia a dia, como pedir informações ou negar algo.', 'Para formar a negação, coloque ''non'' antes do verbo. Para fazer perguntas, basta mudar a entonação da frase afirmativa, ou usar palavras interrogativas como ''chi'', ''che cosa'', ''dove'', ''quando'', ''perché''.', '["Negar uma ação: ''Non parlo inglese.'' (Eu não falo inglês.)","Fazer perguntas sim/não: ''Parli italiano?'' (Você fala italiano?)","Perguntar sobre algo específico: ''Che cosa mangi?'' (O que você come?)","Perguntar sobre lugar: ''Dove abiti?'' (Onde você mora?)"]'::jsonb, '["Esquecer de colocar ''non'' antes do verbo","Usar ''non'' junto com outras palavras negativas duplas em frases simples","Inverter a ordem das palavras em perguntas, como em inglês"]'::jsonb, '["Em italiano, as perguntas geralmente têm a mesma ordem das afirmativas, apenas com entonação diferente. Nas perguntas com palavras interrogativas, a palavra vem no início da frase."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

