insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-66208e418ff9', 'it', 'A1', 'Aggettivi possessivi e dimostrativi', 'Nesta lição, você vai aprender a usar os adjetivos possessivos (meu, seu, nosso...) e os demonstrativos (questo, quello) para indicar posse e localização de pessoas e objetos. Isso é essencial para se comunicar no dia a dia na Itália.', 'Os possessivos concordam em gênero e número com o substantivo. Exemplos: mio (meu), mia (minha), miei (meus), mie (minhas). Os demonstrativos: questo (este, perto de quem fala) e quello (aquele, distante). Eles também concordam com o substantivo: questo libro, questa casa, questi libri, queste case; quello studente, quella donna, quegli uomini, quelle donne.', '["Para indicar posse: Il mio nome è Marco. (Meu nome é Marco.)","Para indicar proximidade: Questo caffè è buono. (Este café é bom.)","Para indicar distância: Quella macchina è rossa. (Aquele carro é vermelho.)","Com palavras como ''piacere'': Mi piace questo libro. (Eu gosto deste livro.)"]'::jsonb, '["Usar o artigo definido antes do possessivo com nomes de parentes no singular: ''il mio padre'' (errado) -> ''mio padre'' (certo).","Confundir ''questo'' e ''quello'' na concordância: ''questo casa'' (errado) -> ''questa casa'' (certo).","Usar o possessivo com o artigo definido quando não é necessário: ''il mio amico'' (certo), mas ''mio amico'' (errado) – na verdade, ''il mio amico'' é correto, mas ''mio amico'' sozinho é errado. O erro comum é omitir o artigo quando deveria estar presente, exceto com parentes no singular.","Não concordar o demonstrativo com o substantivo: ''questi libro'' (errado) -> ''questo libro'' (certo)."]'::jsonb, '["Em italiano, os possessivos geralmente são usados com o artigo definido, exceto com nomes de parentesco no singular (ex: mia madre, non mio madre)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

