insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-d4c9120bfc59', 'it', 'A1', 'Potere, Volere, Dovere: I Verbi Modali', 'Nesta lição, você vai aprender os três verbos modais mais importantes em italiano: potere (poder), volere (querer) e dovere (dever). Esses verbos são usados para expressar possibilidade, vontade e obrigação, e são essenciais para falar sobre ações no dia a dia. Vamos explorar como conjugá-los e usá-los com outros verbos.', 'Os verbos modais são conjugados de forma irregular no presente do indicativo. Eles são sempre seguidos de um verbo no infinitivo.

- **Potere**: io posso, tu puoi, lui/lei può, noi possiamo, voi potete, loro possono.
- **Volere**: io voglio, tu vuoi, lui/lei vuole, noi vogliamo, voi volete, loro vogliono.
- **Dovere**: io devo, tu devi, lui/lei deve, noi dobbiamo, voi dovete, loro devono.

Exemplos: "Posso andare?" (Posso ir?), "Voglio mangiare" (Quero comer), "Devo studiare" (Devo estudar).', '["Potere: per esprimere capacità, permesso o possibilità.","Volere: per esprimere desiderio o volontà.","Dovere: per esprimere obbligo o necessità."]'::jsonb, '["Usare ''potere'' al posto di ''sapere'' per abilità (es. ''so nuotare'' e non ''posso nuotare'').","Dimenticare l''infinito dopo il modale (es. ''voglio andare'', non ''voglio andando'').","Confondere ''devo'' con ''voglio'' quando si esprime un obbligo personale."]'::jsonb, '["1. Os verbos modais são frequentemente usados em perguntas para pedir permissão: ''Posso entrare?''.\n2. ''Dovere'' também pode expressar probabilidade: ''Deve essere tardi''.\n3. Em italiano, não se usa o verbo ''potere'' para habilidades aprendidas; use ''sapere''.\n4. Os modais não têm imperativo próprio; use expressões como ''Devi...'' para dar ordens.\n5. Na forma negativa, ''non posso'' significa ''não posso'' e indica proibição ou impossibilidade."]'::jsonb, 0, true)
