insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-1d748e13611b', 'it', 'A1', 'Simple and Articulated Prepositions', 'As preposições simples e articuladas são essenciais para conectar palavras e formar frases corretas em italiano. Nesta lição, você vai aprender as preposições simples mais comuns (di, a, da, in, con, su, per, tra/fra) e como elas se combinam com artigos definidos (il, lo, la, i, gli, le) para formar preposições articuladas, como ''del'', ''al'', ''dalla'', etc. Vamos praticar com exemplos do dia a dia!', 'As preposições articuladas são formadas unindo uma preposição simples com um artigo definido. Aqui estão as combinações mais comuns:
- di + il = del, di + lo = dello, di + l'' = dell'', di + la = della, di + i = dei, di + gli = degli, di + le = delle
- a + il = al, a + lo = allo, a + l'' = all'', a + la = alla, a + i = ai, a + gli = agli, a + le = alle
- da + il = dal, da + lo = dallo, da + l'' = dall'', da + la = dalla, da + i = dai, da + gli = dagli, da + le = dalle
- in + il = nel, in + lo = nello, in + l'' = nell'', in + la = nella, in + i = nei, in + gli = negli, in + le = nelle
- su + il = sul, su + lo = sullo, su + l'' = sull'', su + la = sulla, su + i = sui, su + gli = sugli, su + le = sulle
- con + il = col (mas também se usa ''con il''), con + lo = con lo, con + l'' = con l'', con + la = con la, con + i = coi (ou ''con i''), con + gli = con gli, con + le = con le
- per e tra/fra geralmente não se combinam com artigos; eles permanecem separados.', '["Usamos preposições simples para indicar posse, movimento, lugar, tempo, modo, etc.","Usamos preposições articuladas quando a preposição é seguida de um artigo definido, indicando algo específico."]'::jsonb, '["Errado: ''Vado a il cinema.'' → Certo: ''Vado al cinema.''","Errado: ''Il libro di il professore.'' → Certo: ''Il libro del professore.''","Errado: ''La chiave è in la borsa.'' → Certo: ''La chiave è nella borsa.''"]'::jsonb, '["Atenção: as preposições articuladas são importantes para soar natural. Pratique-as com nomes de lugares, possessivos e expressões comuns."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

