insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-9b2ef234fe33', 'it', 'A1', 'Mi piace and Piacciono', 'Em italiano, para expressar gostos, usamos o verbo ''piacere''. Ele funciona de forma diferente do português: a coisa que gostamos é o sujeito da frase, e a pessoa que gosta é o objeto indireto. Assim, dizemos ''Mi piace il caffè'' (literalmente: ''O café me agrada''). Se o que gostamos está no plural, usamos ''piacciono''.', 'A estrutura é: [objeto indireto] + [piacere conjugado] + [sujeito (o que gosta)]. Os objetos indiretos são: mi (a mim), ti (a ti), gli (a ele), le (a ela), ci (a nós), vi (a vós), gli (a eles/elas). O verbo ''piacere'' concorda com o sujeito: se o sujeito é singular ou um verbo no infinitivo, usamos ''piace''; se é plural, usamos ''piacciono''. Exemplos: Mi piace la pizza. Mi piacciono le pizze.', '["Para expressar gostos e preferências no presente: ''Mi piace leggere'' (Gosto de ler).","Para falar sobre coisas que gostamos no plural: ''Mi piacciono i libri'' (Gosto de livros).","Com atividades no infinitivo, sempre usamos ''piace'': ''Ti piace ballare?'' (Você gosta de dançar?).","Para perguntar sobre gostos: ''Cosa ti piace?'' (O que você gosta?)."]'::jsonb, '["Não confundir a ordem: em português dizemos ''Eu gosto de música'', mas em italiano é ''Mi piace la musica''. O sujeito é ''la musica''.","Não usar ''io piace'' – o correto é ''mi piace'' (o ''mi'' já indica a pessoa).","Não usar ''piacere'' com o sujeito no plural: se for plural, use ''piacciono''. Ex: ''Mi piacciono i cani'', não ''Mi piace i cani''."]'::jsonb, '["Dica: pense em ''piacere'' como o verbo ''agradar''. A frase ''Mi piace il caffè'' significa literalmente ''O café me agrada''. Isso ajuda a entender a estrutura.","Atenção: o verbo ''piacere'' não é usado como em português. O objeto indireto (mi, ti, etc.) sempre vem antes do verbo.","Lembre-se: com nomes no plural, use ''piacciono''. Exemplo: ''Mi piacciono i cani'' (Eu gosto de cães)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

