insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-c7e88fc79bb4', 'it', 'A1', 'I verbi essere, avere, andare e fare', 'Vamos aprender quatro verbos muito importantes em italiano: essere (ser/estar), avere (ter), andare (ir) e fare (fazer). Eles são irregulares, mas essenciais para formar frases básicas.', 'Presente do indicativo:
- Essere: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono
- Avere: io ho, tu hai, lui/lei ha, noi abbiamo, voi avete, loro hanno
- Andare: io vado, tu vai, lui/lei va, noi andiamo, voi andate, loro vanno
- Fare: io faccio, tu fai, lui/lei fa, noi facciamo, voi fate, loro fanno', '["Essere é usado para identidade, origem, profissão e características físicas ou de personalidade.","Avere é usado para posse, idade, e também em algumas expressões como ''avere fame'' (ter fome).","Andare é usado para movimento, para indicar a direção ou destino.","Fare é usado para ações, como ''fare colazione'' (tomar café da manhã) e ''fare un viaggio'' (fazer uma viagem)."]'::jsonb, '["Confundir ''è'' (verbo essere) com ''e'' (conjunção). Ex.: ''Lui è italiano'' (Ele é italiano) vs. ''Io e lui'' (Eu e ele).","Usar ''avere'' para idade em vez de ''essere'' em português, mas em italiano é correto: ''Io ho 30 anni''.","Esquecer que ''andare'' é usado com a preposição ''a'' + artigo, como ''vado a casa''? Não, normalmente ''vado a casa'' é usado sem artigo, mas ''vado al cinema''.","Não conjugar corretamente ''fare'' na primeira pessoa: ''io faccio'' e não ''io fado''."]'::jsonb, '["Atenção: ''andare'' e ''fare'' são irregulares. Pratique a conjugação diariamente. Lembre-se que em italiano, o sujeito muitas vezes é omitido porque a conjugação já indica a pessoa."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

