insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-783227ed7d08', 'it', 'A1', 'Verbi Regolari e Irregolari al Presente (Present Simple)', 'Nesta lição, você vai aprender como conjugar verbos no presente do indicativo em italiano, incluindo verbos regulares e alguns irregulares comuns, como ''essere'' e ''avere''.', 'Para verbos regulares, remova a desinência do infinitivo (-are, -ere, -ire) e adicione as terminações apropriadas para cada pessoa. Por exemplo, ''parlare'' (falar) fica: io parlo, tu parli, lui/lei parla, noi parliamo, voi parlate, loro parlano. Verbos irregulares como ''essere'' e ''avere'' têm formas próprias que devem ser memorizadas: essere: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono; avere: io ho, tu hai, lui/lei ha, noi abbiamo, voi avete, loro hanno.', '[{"description":"Use o presente para falar de ações habituais.","title":"Falar sobre rotina"},{"description":"Para expressar fatos e dar informações pessoais.","title":"Dar informações"},{"description":"Para descrever estados emocionais ou opiniões.","title":"Expressar sentimentos e pensamentos"}]'::jsonb, '[{"description":"Misturar as desinências entre os grupos -are, -ere, -ire.","title":"Confundir as terminações"},{"description":"Não memorizar as formas de ''essere'' e ''avere''.","title":"Esquecer os verbos irregulares"},{"description":"Às vezes, o presente é usado para o futuro, mas deve-se ter cuidado.","title":"Usar o presente para ações futuras"}]'::jsonb, '["Atenção: o sujeito muitas vezes pode ser omitido em italiano, pois a terminação do verbo já indica a pessoa."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

