insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-e5d34e63a5de', 'it', 'A1', 'La negazione e le domande', 'Nesta lição, você vai aprender como formar frases negativas e fazer perguntas simples em italiano.', 'Para formar a negação, coloque ''non'' antes do verbo. Para fazer perguntas, basta mudar a entonação da frase afirmativa ou usar palavras interrogativas como ''chi'', ''che cosa'', ''dove'', ''quando'', ''perché'', ''come''.', '["Para negar uma ação: Non mangio carne. (Não como carne.)","Para fazer perguntas sim/não: Vieni domani? (Você vem amanhã?)","Para perguntar sobre pessoas: Chi è lui? (Quem é ele?)","Para perguntar sobre coisas: Che cosa è questo? (O que é isso?)","Para perguntar sobre lugares: Dove abiti? (Onde você mora?)","Para perguntar sobre tempo: Quando parti? (Quando você parte?)","Para perguntar sobre motivos: Perché sei triste? (Por que você está triste?)","Para perguntar sobre modo: Come stai? (Como você está?)"]'::jsonb, '["Colocar ''non'' depois do verbo. O correto é antes do verbo.","Usar ''non'' em perguntas (a menos que seja uma pergunta negativa, como ''Non vieni?'').","Esquecer de usar a entonação de pergunta, que em italiano é similar ao português.","Confundir ''che cosa'' com ''cosa'' – ambos são corretos, mas ''che cosa'' é mais formal."]'::jsonb, '["Na língua falada, muitas vezes se omitem os sujeitos: ''Vieni?'' em vez de ''Tu vieni?''.","A negação dupla é usada com ''non...nessuno'', ''non...niente'', etc.","Para perguntas, muitas vezes a entonação é essencial, pois a ordem das palavras não muda."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

