insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-348386051bb2', 'it', 'A1', 'Possessivi e dimostrativi', 'Os possessivos indicam posse (meu, seu, nosso) e os demonstrativos indicam proximidade (este, esse, aquele). Nesta lição, você aprenderá a usá-los com substantivos no singular e plural.', 'Os possessivos geralmente são precedidos pelo artigo definido (il mio, la mia, i miei, le mie). Os demonstrativos, por sua vez, são: questo (perto de quem fala), quello (longe de quem fala). Eles variam em gênero e número: questo/questa/questi/queste; quello/quella/quelli/quelle.', '["Para expressar posse: ''Il mio libro è qui.''","Para falar de algo perto de você: ''Questa casa è bella.''","Para falar de algo longe: ''Quella macchina è di Maria.''","Para identificar algo: ''Questo è il mio telefono.''"]'::jsonb, '["Esquecer o artigo definido com possessivos: ''mio libro'' em vez de ''il mio libro''.","Confundir ‘questo’ (perto) com ‘quello’ (longe).","Não alterar o gênero/número: ''questi libri'' não é ''questo libri''."]'::jsonb, '["Os possessivos ''mio'', ''tuo'', ''suo'', ''nostro'', ''vostro'', ''loro'' normalmente usam artigo, exceto com nomes de parentesco no singular (es. ''mia madre'').","Nesta lição, vamos focar no uso básico com artigo definido."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

