insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-e9f33e14ed09', 'it', 'A1', 'Potere, Volere, Dovere (Basic)', 'Os verbos modais potere, volere e dovere são muito usados para expressar possibilidade, vontade, necessidade e obrigação. Aprender suas formas básicas no presente vai ajudar você a se comunicar melhor.', 'No presente, eles são irregulares. Observe a conjugação: POTERE: io posso, tu puoi, lui/lei può, noi possiamo, voi potete, loro possono. VOLERE: io voglio, tu vuoi, lui/lei vuole, noi vogliamo, voi volete, loro vogliono. DOVERE: io devo, tu devi, lui/lei deve, noi dobbiamo, voi dovete, loro devono.', '["Potere: permissão ou possibilidade: Posso entrare?","Volere: desejo ou vontade: Voglio un caffè.","Dovere: obrigação ou necessidade: Devo studiare.","Uso com infinitivo: os modais são seguidos pelo infinitivo do verbo principal: Posso andare."]'::jsonb, '["Não confundir as formas: ''io posso'' (não ''io potere'').","Usar ''devo'' (não ''debbo'') como forma padrão.","Lembrar de usar o infinitivo após o modal: ''Voglio mangiare'' (não ''Voglio mangi''.)","Não usar o subjuntivo após os modais em frases simples."]'::jsonb, '["Os modais são frequentemente usados em perguntas polidas: Potrebbe aiutarmi? (formal).","No A1, use principalmente o presente.","Preste atenção à diferença entre ''sapere'' (saber) e ''potere'' (poder)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

