insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-0543cc3be8e1', 'it', 'A1', 'Preposizioni Semplici e Articolate', 'Nesta lição, você vai aprender as preposições simples e articuladas em italiano. As preposições são palavras que ligam ideias, como ''di'', ''a'', ''da'', ''in'', ''con'', ''su'', ''per'', ''tra'', ''fra''. Quando combinadas com os artigos definidos (il, lo, la, i, gli, le), formam as preposições articoladas, como ''del'', ''alla'', ''dalla'', ''nel'', ''sul''. Vamos ver como usá-las no dia a dia!', 'As preposições simples são: di, a, da, in, con, su, per, tra, fra. Para formar as articuladas, combine a preposição com o artigo definido:
- di + il = del, di + lo = dello, di + la = della, di + i = dei, di + gli = degli, di + le = delle
- a + il = al, a + lo = allo, a + la = alla, a + i = ai, a + gli = agli, a + le = alle
- da + il = dal, da + lo = dallo, da + la = dalla, da + i = dai, da + gli = dagli, da + le = dalle
- in + il = nel, in + lo = nello, in + la = nella, in + i = nei, in + gli = negli, in + le = nelle
- con + il = col, con + lo = collo (raro), con + la = colla (raro), con + i = coi, con + gli = cogli (raro), con + le = colle (raro)
- su + il = sul, su + lo = sullo, su + la = sulla, su + i = sui, su + gli = sugli, su + le = sulle
As preposições per, tra, fra não se articulam.', '["Indicar posse ou origem: ''Il libro di Maria'' (o livro de Maria).","Indicar lugar: ''Vado a Roma'' (vou a Roma), ''Vivo in Brasile'' (moro no Brasil). Uso de ''in'' com países, ''a'' com cidades.","Indicar tempo: ''Alle otto'' (às oito), ''Nel pomeriggio'' (à tarde).","Indicar meio: ''Vado in macchina'' (vou de carro), ''Scrivo con la penna'' (escrevo com a caneta).","Indicar assunto: ''Parlo di lavoro'' (falo sobre trabalho)."]'::jsonb, '["Confundir ''di'' (posse) com ''da'' (origem): ''Sono di Roma'' (sou de Roma) mas ''Vengo da Roma'' (venho de Roma).","Usar ''in'' com cidades: ''Vado in Milano'' errado; correto: ''Vado a Milano''.","Esquecer a articulação: ''il libro del professore'' não ''il libro di il professore''.","Usar ''tra'' ou ''fra'' com artigos: ''tra gli amici'' ok, mas não ''tra gli''? Na verdade é correto, mas não articulada."]'::jsonb, '["1. As formas com ''con'' (col, coi) são comuns na língua falada, mas podem ser evitadas. 2. ''Tra'' e ''fra'' são sinônimos, mas nunca se articulam. 3. Preste atenção ao gênero e número do substantivo. 4. Em italiano, muitas vezes a preposição articulada é obrigatória onde em português usaríamos ''de + o'', ''em + o'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

