insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-d21b4f6bb4ec', 'it', 'A1', 'La Quantità di Base: Quanto, Quanti, Poco, Molto', 'Nesta lição, você vai aprender a expressar quantidades básicas em italiano. Isso é essencial para fazer compras, pedir comida e falar sobre o que você tem.', 'Use ''quanto'' (quanto) e ''quanti'' (quantos) para perguntar sobre quantidade. Use ''molto'' (muito/muita) e ''poco'' (pouco/pouca) para falar de quantidade. ''Molto'' e ''poco'' concordam em gênero e número com o substantivo.', '["Para perguntar sobre preço: ''Quanto costa?'' (Quanto custa?)","Para perguntar sobre número de pessoas: ''Quanti siete?'' (Quantos vocês são?)","Para falar de grande quantidade: ''C''è molto cibo.'' (Há muita comida.)","Para falar de pequena quantidade: ''Ho poca fretta.'' (Tenho pouca pressa.)"]'::jsonb, '["Usar ''quanto'' invariável com substantivos femininos ou plurais. Ex.: ''Quanti libri?'' (não ''Quanto libri'').","Esquecer a concordância de ''molto'' e ''poco'' com o substantivo. Ex.: ''mole acqua'' (errado, é ''molta acqua'').","Usar ''quanto'' para perguntar preço de plural: ''Quanto costano le mele?'' (não ''Quanto costa le mele'')."]'::jsonb, '["Lembre-se que ''quanto'' pode ser também um advérbio em frases como ''Quanto sei alto!'' (Como você é alto!). Nesta lição, focamos no uso como adjetivo e pronome."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

