insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-d7de3cba91e8', 'it', 'A1', 'Presente dei Verbi in -IRE (tipo ''capire'')', 'Nesta lição, você vai aprender o presente do indicativo dos verbos em -IRE com inserção de -ISC- (como ''capire'', ''finire'', ''preferire''). Esses verbos são muito comuns no italiano do dia a dia e são essenciais para falar de ações habituais, preferências e coisas que estão acontecendo agora.', 'Para formar o presente, tire a terminação -IRE do infinitivo e adicione as seguintes desinências: -isco, -isci, -isce, -iamo, -ite, -iscono. Exemplo com ''capire'': io capisco, tu capisci, lui/lei capisce, noi capiamo, voi capite, loro capiscono.', '["Para expressar ações habituais (ex: Ogni giorno finisco il lavoro alle 18).","Para falar de preferências (ex: Preferisco il tè al caffè).","Para descrever ações em andamento (ex: Sto capendo la lezione).","Para pedir informações de forma educada (ex: Capisce l''italiano?).","Para expressar sentimentos e sensações (ex: Sento freddo)."]'::jsonb, '["Não acrescentar -isc- na primeira pessoa: ''io capo'' em vez de ''io capisco''.","Confundir as desinências: usar -o em vez de -isco na primeira pessoa (capo em vez de capisco).","Errar a terceira pessoa do plural: loro capiscono, não ''loro capiscono'' sem o -s-.","Usar a forma de indicativo em contextos de subjuntivo (mas isso é nível mais avançado)."]'::jsonb, '["Os verbos em -IRE que seguem este padrão incluem: capire, finire, pulire, spedire, preferire, costruire, agire, e molti altri. Alguns verbos em -IRE não têm o -isc-, como ''dormire'' e ''partire''; preste atenção neles."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

