insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-a0d3c9cc4943', 'it', 'A1', 'Possessivi e Dimostrativi', 'Os possessivos e demonstrativos são palavras que indicam posse ou localização. Os possessivos (meu, tua, seu, etc.) mostram a quem algo pertence. Os demonstrativos (questo, quello) indicam se algo está perto ou longe de quem fala.', 'Em italiano, os possessivos geralmente são precedidos de artigo definido (il mio, la mia, i miei, le mie). Os demonstrativos: questo (este, perto) e quello (aquele, longe). Eles concordam em gênero e número com o substantivo.', '["Para expressar posse: ''Il mio libro'' (meu livro).","Para indicar algo próximo: ''Questo tavolo'' (esta mesa).","Para indicar algo distante: ''Quel ragazzo'' (aquele menino).","Com parentes no singular, geralmente sem artigo: ''mio padre'' (meu pai)."]'::jsonb, '["Esquecer o artigo: ''mio libro'' em vez de ''il mio libro'' (exceto com parentes singulares).","Confundir ''questo'' e ''quello'' na distância.","Não concordar gênero e número: ''questa libri'' (errado) vs. ''questi libri''.","Usar ''suo'' para ''deles'' (correto é ''loro'')."]'::jsonb, '["O possessivo ''loro'' é invariável. ''Proprio'' é usado como possessivo reflexivo. Os demonstrativos têm formas abreviadas: ''quel'', ''quella'', ''quelli'', ''quelle''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

