insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-5792dccfb8b3', 'it', 'A1', 'Preposizioni Semplici e Articolate', 'Nesta lição, você vai aprender as preposições simples e articuladas em italiano. As preposições simples são palavras como ''di'', ''a'', ''da'', ''in'', ''con'', ''su'', ''per'', ''tra'', ''fra''. Quando combinadas com artigos definidos (il, lo, la, i, gli, le), formam as preposições articuladas, como ''del'', ''alla'', ''dallo'', etc. Isso é muito comum no italiano do dia a dia.', 'Para formar as preposições articuladas, combine a preposição com o artigo definido. Por exemplo: di + il = del, di + la = della, a + il = al, a + la = alla, da + il = dal, da + la = dalla, in + il = nel, in + la = nella, su + il = sul, su + la = sulla. Existem também formas para o plural: di + i = dei, di + gli = degli, etc.', '["Para indicar posse ou origem: ''Il libro è di Maria'' (O livro é de Maria).","Para indicar movimento para um lugar: ''Vado al mercato'' (Vou ao mercado).","Para indicar proveniência: ''Vengo da Roma'' (Venho de Roma).","Para indicar meio de transporte: ''Viaggio in treno'' (Viajo de trem).","Para indicar superfície: ''Il libro è sul tavolo'' (O livro está sobre a mesa)."]'::jsonb, '["Usar a preposição simples em vez da articulada quando necessário. Por exemplo: ''Vado a il mercato'' em vez de ''Vado al mercato''.","Confundir ''di'' com ''da'' em contextos de origem. Lembre-se: ''da'' é para proveniência, ''di'' para posse.","Esquecer de combinar a preposição com o artigo em expressões fixas."]'::jsonb, '["Nem todas as preposições se combinam com artigos. ''per'', ''tra'', ''fra'' não formam preposições articuladas. Algumas combinações são irregulares, como ''di + il = del'' e ''in + il = nel''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

