insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-f3c05b4838fb', 'it', 'A1', 'Mi piace: Expressing Likes and Preferences', 'Nesta lição, você vai aprender a usar a estrutura ''mi piace'' e ''mi piacciono'' para expressar gostos e preferências em italiano.', 'Use ''mi piace'' + singular noun or verb infinitive. Use ''mi piacciono'' + plural noun.', '[{"example":"Mi piace la pizza.","use_case":"Likes with singular nouns"},{"example":"Mi piacciono le mele.","use_case":"Likes with plural nouns"},{"example":"Mi piace leggere.","use_case":"Likes with verbs (activities)"},{"example":"Non mi piace il calcio.","use_case":"Dislikes"}]'::jsonb, '[{"correction":"Use ''mi piacciono'' with plural nouns.","mistake":"Using ''mi piace'' with plural nouns."},{"correction":"The correct form for present tense is ''mi piace''.","mistake":"Using ''mi piacere'' instead of ''mi piace''."},{"correction":"Use ''non'' before ''mi piace'' or ''mi piacciono'' to make negative statements.","mistake":"Forgetting ''non'' for negative."}]'::jsonb, '["Use ''mi piace'' quando a coisa que você gosta é singular (ex: ''mi piace il gelato'').","Use ''mi piacciono'' quando a coisa que você gosta é plural (ex: ''mi piacciono le mele'').","Quando você gosta de uma atividade (verbo no infinitivo), use sempre ''mi piace'' (ex: ''mi piace leggere'').","Para formar a negativa, coloque ''non'' antes de ''mi'' (ex: ''non mi piace il caffè'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

