insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-b219acf22e78', 'it', 'A1', 'Quantità di base in italiano (A1): ''Quanto/a/i/e'', ''molto/a/i/e'', ''troppo/a/i/e'', ''poco/a/i/e''', 'Nesta lição, você vai aprender a falar sobre quantidades básicas em italiano. Vamos usar palavras como ''quanto'' (quanto), ''molto'' (muito), ''troppo'' (demais) e ''poco'' (pouco) para descrever quantidades. Isso é essencial para fazer perguntas e descrever coisas no dia a dia.', 'Essas palavras concordam em gênero e número com o substantivo que modificam. As formas são: maschile singolare: -o (quanto, molto, troppo, poco); femminile singolare: -a (quanta, molta, troppa, poca); maschile plurale: -i (quanti, molti, troppi, pochi); femminile plurale: -e (quante, molte, troppe, poche). Exemplo: ''Quanti libri hai?'' (Quantos livros você tem?) / ''Ho molti libri.'' (Tenho muitos livros.)', '["Para perguntar sobre quantidade: ''Quanto pane vuoi?'' (Quanto pão você quer?)","Para expressar quantidade grande: ''Ho molto lavoro.'' (Tenho muito trabalho.)","Para expressar quantidade excessiva: ''C''è troppo zucchero.'' (Tem açúcar demais.)","Para expressar quantidade pequena: ''Ho pochi amici.'' (Tenho poucos amigos.)"]'::jsonb, '["Usar a forma masculina singular com substantivos femininos: ''molto amici'' (errado) → ''molti amici'' (correto).","Usar ''molto'' invariável antes de substantivos: ''molto libri'' (errado) → ''molti libri'' (correto).","Confundir ''poco'' (pouco) e ''un po'' (um pouco). ''Ho poco tempo.'' (Tenho pouco tempo.) vs. ''Ho un po'' di tempo.'' (Tenho um pouco de tempo.)"]'::jsonb, '["Essas palavras também podem ser usadas como advérbios (invariáveis) com verbos ou adjetivos: ''Lavoro molto.'' (Trabalho muito.) / ''È troppo caro.'' (É caro demais.)"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

