insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-cf2e04b09812', 'it', 'A1', 'I verbi essere, avere, andare, fare', 'Nesta aula, você vai aprender os quatro verbos mais importantes em italiano: essere (ser/estar), avere (ter), andare (ir) e fare (fazer). Eles são irregulares, mas muito usados no dia a dia.', 'Eles são irregulares, então é preciso memorizar as formas. Aqui estão as conjugações no presente do indicativo:

Essere: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono
Avere: io ho, tu hai, lui/lei ha, noi abbiamo, voi avete, loro hanno
Andare: io vado, tu vai, lui/lei va, noi andiamo, voi andate, loro vanno
Fare: io faccio, tu fai, lui/lei fa, noi facciamo, voi fate, loro fanno', '["Essere: para identidade, nacionalidade, profissão, características e estado. Ex: Io sono brasiliano.","Avere: para posse, idade e algumas sensações. Ex: Ho 30 anni. Ho fame.","Andare: para movimento, ir a algum lugar. Ex: Vado a casa.","Fare: para ações, fazer alguma coisa, falar de tempo. Ex: Che tempo fa? Fa caldo."]'::jsonb, '["Confundir essere e avere: ''Sono 30 anni'' (errado) vs ''Ho 30 anni'' (certo).","Usar ''io è'' ou ''io ha'' – sempre ''io sono'' e ''io ho''.","Esquecer a preposição com andare: ''Vado a casa'' não ''Vado casa''.","Formas irregulares: ''faccio'' e ''vado'' não ''faco'' ou ''vo''."]'::jsonb, '["Estes verbos são fundamentais e aparecem em muitas expressões. Pratique diariamente."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

