insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-31402c7ccf2e', 'it', 'A1', 'C''è / Ci sono', 'Em italiano, usamos ''c''è'' (singular) e ''ci sono'' (plural) para dizer ''há'', ''existe'' ou ''existem''. É uma construção muito comum no dia a dia.', 'C''è + substantivo singular (ex: C''è un libro sul tavolo.)
Ci sono + substantivo plural (ex: Ci sono due libri sul tavolo.)
A forma negativa é: non c''è / non ci sono. Para perguntar: C''è...? / Ci sono...?', '["Para indicar a existência de algo ou alguém em um lugar.","Para dizer o que há em um ambiente, como ''Na sala há uma mesa.''","Para perguntar se há algo disponível, como ''Há café?''","Na forma negativa, para dizer que algo não existe ou não está presente."]'::jsonb, '["Usar ''c''è'' com plural: Errado: ''C''è due libri.'' Certo: ''Ci sono due libri.''","Esquecer a contração: ''ci è'' em vez de ''c''è''.","Usar ''avere'' em vez de ''c''è'': ''Ho un libro'' está certo, mas para existência usamos ''c''è''."]'::jsonb, '["Lembre-se: ''c''è'' é usado para singular, ''ci sono'' para plural.","Na pergunta, inverte-se a ordem: ''C''è un problema?'' ou ''Ci sono problemi?''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

