insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-ec3c1392424c', 'it', 'A1', 'La Negazione e le Domande in Italiano', 'In questa lezione, imparerai come formare frasi negative e domande in italiano, fondamentali per comunicare in situazioni quotidiane.', 'Per formare la negazione, si mette ''non'' prima del verbo. Per le domande, si usa l''intonazione ascendente o il punto interrogativo; la struttura della frase rimane quella dichiarativa.', '["Per negare un''azione: ''Non mangio carne.'' (Não como carne.)","Per fare una domanda: ''Mangi carne?'' (Você come carne?)","Per chiedere una negazione: ''Non mangi carne?'' (Você não come carne?)"]'::jsonb, '["Mettere ''non'' dopo il verbo: ''Mangio non carne.'' (Errado: o correto é ''Non mangio carne.'')","Usare ''non'' nelle domande senza cambiare l''intonazione: ''Non mangi carne?'' deve avere intonazione ascendente."]'::jsonb, '["In italiano, le domande si formano principalmente con l''intonazione o con parole interrogative, senza ausiliari come ''do''.","La negazione ''non'' si colloca sempre prima del verbo coniugato.","Nelle domande negative, ''non'' resta prima del verbo e l''intonazione sale."]'::jsonb, 0, true)
