insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-c974ff828f67', 'it', 'A1', 'Possessivi e Dimostrativi', 'Nesta lição, você vai aprender a usar os adjetivos possessivos (meu, seu, nosso etc.) e os demonstrativos (questo, quello) para indicar posse e localização. Isso é essencial para falar sobre objetos, pessoas e lugares no dia a dia.', 'Os possessivos concordam em gênero (masculino/feminino) e número (singular/plural) com o substantivo: il mio libro, la mia casa, i miei amici, le mie amiche. Os demonstrativos: questo (este, perto) e quello (aquele, longe) também concordam: questo libro, questa casa, questi libri, queste case; quel libro, quella casa, quei libri, quelle case.', '["Indicar posse: La mia famiglia è grande.","Perguntar de quem é: Di chi è questo telefono?","Distinguir perto/longe: Questo è il mio caffè, quello è il tuo.","Falar de partes do corpo: Mi fa male la testa (usa artigo, não possessivo)."]'::jsonb, '["Confundir ''suo'' com ''loro'' – ''suo'' = dele/dela, ''loro'' = deles/delas.","Usar possessivo com partes do corpo (em italiano, normalmente se usa artigo).","Esquecer a concordância: ''i mia amici'' (errado) vs ''i miei amici'' (correto).","Confundir ''questo'' (perto) com ''quello'' (longe)."]'::jsonb, '["Antes de um substantivo, o possessivo normalmente vem com artigo definido, exceto com nomes de parentesco no singular (es. mia madre)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

