insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-fff09f3fd018', 'it', 'A1', 'Potere, Volere, Dovere: I Verbi Modali', 'Nesta lição, você vai aprender os verbos modais italiani: potere (poder), volere (querer) e dovere (dever). Esses verbos são essenciais para expressar possibilidade, vontade e obrigação. Você vai ver como conjugá-los no presente e como usá-los com outros verbos no infinitivo.', 'No presente do indicativo, os verbos modais são irregulares. Veja as formas:

**Potere** (poder)
- io posso
- tu puoi
- lui/lei può
- noi possiamo
- voi potete
- loro possono

**Volere** (querer)
- io voglio
- tu vuoi
- lui/lei vuole
- noi vogliamo
- voi volete
- loro vogliono

**Dovere** (dever)
- io devo
- tu devi
- lui/lei deve
- noi dobbiamo
- voi dovete
- loro devono

Para usar um verbo modal com outro verbo, coloque o modal na forma conjugada seguido do infinitivo: Exemplo: ''Io posso parlare italiano.''', '[{"case":"Potere: usado para expressar capacidade, permissão ou possibilidade.","example":"Posso uscire? (Posso sair?)"},{"case":"Volere: usado para expressar desejo ou vontade.","example":"Voglio un caffè. (Quero um café.)"},{"case":"Dovere: usado para expressar obrigação ou necessidade.","example":"Devo studiare. (Preciso estudar.)"}]'::jsonb, '[{"correction":"Lembre-se: ''posso'' é de potere, ''voglio'' é de volere.","mistake":"Confundir as formas de ''potere'' e ''volere'' na primeira pessoa (posso vs. voglio)."},{"correction":"Depois de potere, volere, dovere, sempre use o verbo no infinitivo.","mistake":"Esquecer de usar o infinitivo depois do modal."},{"correction":"''deve'' é para ele/ela, ''devo'' é para io.","mistake":"Usar ''devo'' ao invés de ''deve'' para a terceira pessoa."}]'::jsonb, '["Os verbos modais são frequentemente usados com outros verbos no infinitivo, sem preposição.","Em perguntas, o sujeito pode ser omitido: ''Posso?'' em vez de ''Io posso?''.","No italiano falado, muitas vezes se usa ''non posso'' para dizer ''não posso''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

