insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-e5c62b85d147', 'it', 'A1', 'Simple and Articulated Prepositions', 'Em italiano, as preposições simples (di, a, da, in, con, su, per, tra, fra) podem se combinar com os artigos definidos (il, lo, la, i, gli, le) formando as preposições articuladas, como ''del'', ''al'', ''dal'', ''nel'', ''sul''. Essas formas são muito usadas no dia a dia para indicar posse, lugar, tempo e outras relações.', 'Para formar as preposições articuladas, combine a preposição com o artigo definido, seguindo as regras:
- di + il = del, di + lo = dello, di + la = della, di + i = dei, di + gli = degli, di + le = delle
- a + il = al, a + lo = allo, a + la = alla, a + i = ai, a + gli = agli, a + le = alle
- da + il = dal, da + lo = dallo, da + la = dalla, da + i = dai, da + gli = dagli, da + le = dalle
- in + il = nel, in + lo = nello, in + la = nella, in + i = nei, in + gli = negli, in + le = nelle
- su + il = sul, su + lo = sullo, su + la = sulla, su + i = sui, su + gli = sugli, su + le = sulle', '["Indicar posse: ''Il libro è del professore.''","Indicar lugar: ''Vado al mercato.''","Indicar origem: ''Vengo dalla Brasile.''","Indicar tempo: ''Arrivo alle tre.''","Indicar meio: ''Viaggio in treno.''","Indicar argumento: ''Parlo del lavoro.''"]'::jsonb, '["Usar ''dei'' em vez de ''del'' com nomes masculinos singulares (ex.: ''dei libro'' em vez de ''del libro'').","Esquecer a combinação e usar preposição e artigo separados (ex.: ''a il'' em vez de ''al'').","Confundir ''nel'' com ''in il'' – sempre use ''nel''.","Usar ''della'' para masculino (ex.: ''della libro'' em vez de ''del libro'').","Não usar a forma articulada quando necessário (ex.: ''vado a scuola'' em vez de ''vado alla scuola'' quando específico).","Aplicar a mesma forma para todos os artigos (ex.: usar ''del'' para todos os gêneros)."]'::jsonb, '["1. As preposições ''tra'' e ''fra'' não se combinam com artigos definidos. Ex.: ''tra i libri''.\n2. A preposição ''per'' não se combina com artigos definidos. Ex.: ''per il bambino''.\n3. Com nomes de lugares, muitas vezes se usa a preposição articulada: ''vado al cinema'' (não ''a il cinema'').\n4. Com nomes de países, ''in'' não se combina: ''in Italia'' (não ''nella Italia'').\n5. A escolha da forma articulada depende do gênero, número e da letra inicial do nome.\n6. É importante memorizar as combinações mais comuns.\n7. As preposições articuladas são usadas também em expressões idiomáticas.\n8. Em italiano, a preposição ''di'' antes de vogal pode ser apostrofada: ''dell''amico''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

