insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a1-120f080e4da4', 'it', 'A1', 'Quanto e Quanti: Quantità di Base in Italiano', 'In questa lezione imparerai a usare ''quanto'' e ''quanti'' per fare domande sulla quantità, come ''Quanto tempo?'' o ''Quanti caffè?''. Questo è essenziale per le conversazioni quotidiane, come fare la spesa o prendere appuntamenti.', 'Usa ''quanto'' + sostantivo singolare maschile (es: quanto pane). Usa ''quanta'' + sostantivo singolare femminile (es: quanta acqua). Usa ''quanti'' + sostantivo plurale maschile (es: quanti libri). Usa ''quante'' + sostantivo plurale femminile (es: quante amiche).', '["Per chiedere il prezzo: Quanto costa?","Per chiedere l''età: Quanti anni hai?","Per chiedere il tempo: Quanto tempo?","Per chiedere il numero di oggetti: Quanti libri hai?"]'::jsonb, '["Dire ''Quanto libri?'' invece di ''Quanti libri?'' (accordo con il plurale maschile).","Confondere ''quanto'' (singolare) con ''quanti'' (plurale).","Usare ''quanto'' con sostantivi femminili plurali: ''quanto amiche'' invece di ''quante amiche''."]'::jsonb, '["In italiano, ''quanto'' concorda in genere e numero con il sostantivo. Per esempio: ''quanto pane'' (maschile singolare), ''quanta acqua'' (femminile singolare), ''quanti libri'' (maschile plurale), ''quante amiche'' (femminile plurale).","Quando si chiede il prezzo, si usa sempre ''quanto'' nella forma invariabile: ''Quanto costa?''.","Per chiedere l''età, si usa ''quanti'': ''Quanti anni hai?''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

